#include <vector>
using namespace std;

class Solution {
public:
    int boxDelivering(vector<vector<int>>& boxes, int portsCount, int maxBoxes, int maxWeight) {
        int n = boxes.size();
        vector<int> dp(n + 1, 0);
        int j = 0;
        int weight = 0;
        int trips = 2;
        for (int i = 0; i < n; ++i) {
            weight += boxes[i][1];
            if (i > 0 && boxes[i][0] != boxes[i - 1][0]) {
                trips++;
            }
            while (i - j >= maxBoxes || weight > maxWeight || (j < i && dp[j] == dp[j + 1])) {
                weight -= boxes[j][1];
                if (boxes[j][0] != boxes[j + 1][0]) {
                    trips--;
                }
                j++;
            }
            dp[i + 1] = dp[j] + trips;
        }
        return dp[n];
    }
};

