var boxDelivering = function(boxes, portsCount, maxBoxes, maxWeight) {
    const n = boxes.length;
    const dp = Array(n + 1).fill(0);
    let j = 0;
    let weight = 0;
    let trips = 2;
    for (let i = 0; i < n; ++i) {
        weight += boxes[i][1];
        if (i > 0 && boxes[i][0] !== boxes[i - 1][0]) {
            trips++;
        }
        while (i - j >= maxBoxes || weight > maxWeight || (j < i && dp[j] === dp[j + 1])) {
            weight -= boxes[j][1];
            if (boxes[j][0] !== boxes[j + 1][0]) {
                trips--;
            }
            j++;
        }
        dp[i + 1] = dp[j] + trips;
    }
    return dp[n];
